"use strict";(globalThis.webpackChunkuniwahl_doku||=[]).push([[1364],{4154(e,n,i){i.r(n),i.d(n,{assets:()=>d,contentTitle:()=>l,default:()=>o,frontMatter:()=>a,metadata:()=>r,toc:()=>h});const r=JSON.parse('{"id":"releases/6.0","title":"Version 6.0","description":"\ud83d\ude80 Dieses Release \xfcberarbeitet die vorherige Version 5 von uniWAHL in zahlreichen Aspekten der Benutzeroberfl\xe4che.","source":"@site/docs/releases/6.0.md","sourceDirName":"releases","slug":"/releases/6.0","permalink":"/uniwahl-doku/pr-preview/pr-5/releases/6.0","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"title":"Version 6.0"},"sidebar":"doku","previous":{"title":"Version 6.1","permalink":"/uniwahl-doku/pr-preview/pr-5/releases/6.1"},"next":{"title":"Zus\xe4tzliche Inhalte","permalink":"/uniwahl-doku/pr-preview/pr-5/download/zusatz"}}');var t=i(4848),s=i(8453);const a={title:"Version 6.0"},l=void 0,d={},h=[];function u(e){const n={li:"li",p:"p",strong:"strong",ul:"ul",...(0,s.R)(),...e.components};return(0,t.jsxs)(t.Fragment,{children:[(0,t.jsx)(n.p,{children:"\ud83d\ude80 Dieses Release \xfcberarbeitet die vorherige Version 5 von uniWAHL in zahlreichen Aspekten der Benutzeroberfl\xe4che."}),"\n",(0,t.jsxs)(n.ul,{children:["\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsx)(n.strong,{children:"\xdcberarbeitetes Erscheinungsbild"}),": Durch ein flacheres Design der Fenster, \xdcberarbeitung der Farbgebung und Entfernen von Rahmen und Schattierungen wirkt uniWAHL moderner und \xfcbersichtlicher. Die Dialoge und Schriften wurden vergr\xf6\xdfert und sind dadurch in der (Standard-)Skalierung FHD besser lesbar. Die Registerkarte \u201eKandidaten-\xdcbersicht\u201c wurde in den Wahlbereichen entfernt, damit der Fokus in der Bedienung zentral auf dem linken Navigationsfeld gehalten werden kann. Die modalen Fenster der Dialoge zum Wahlprojekt, der Gremien, der Wahlbereiche, Listen und Kandidat",":innen"," wurden durch eine Vollbilddarstellung ersetzt. Verschiedene Fenster \xfcberlappen sich im Hauptfenster von uniWAHL nun nicht mehr. Die moduslosen Dialogfelder werden konsistent in der Benutzeroberfl\xe4che gehalten, so dass alle Schaltfl\xe4chen der Dialoge immer an der gleichen Stelle zu finden sind. Inhalte k\xf6nnen dadurch beim Wechsel von Dialogen \xfcber das linke Navigatorfeld leichter im Fokus behalten werden."]}),"\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsx)(n.strong,{children:"Automatisches Speichern bei Fensterwechsel"}),": Beim Wechsel des Eingabefensters \xfcber den linken Navigationsbereich werden die Eingaben in den Dialogen zum Wahlprojekt, der Gremien, der Wahlbereiche, Listen und Kandidat",":innen"," nun automatisch gespeichert. Es muss nicht mehr explizit die Schaltfl\xe4che \u201eSpeichern\u201c geklickt werden. Dadurch entfallen zus\xe4tzliche Klicks und die Fenster lassen sich in der Bearbeitung der Wahlbereiche schneller wechseln. Die Men\xfcdialoge wie \u201eKonfiguration / Wahlordnung\u201c oder \u201eKonfiguration / Layout der Dokumente\u201c werden weiterhin als eigenst\xe4ndige Dialoge angeboten und k\xf6nnen nun \xfcber das Dr\xfccken der ESC-Taste schneller geschlossen werden, wenn z.B. nur schnell etwas gepr\xfcft werden soll, ohne die Eingaben zu ver\xe4ndern. Beim Klick auf \u201eAbbrechen\u201c oder Dr\xfccken der ESC-Taste wird in allen Fenstern weiterhin ein Dialog angeboten, der das manuelle Speichern erm\xf6glicht. Alle Eingaben werden konsequent in den uniWAHL-Sicherungskopien gespeichert und k\xf6nnen anschlie\xdfend wie gewohnt \xfcber das Men\xfc \u201eDatei / Speichern\u201c oder \u201eSpeichern unter\u2026\u201c im Wahlprojekt (der WHL-Datei) gespeichert werden."]}),"\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsx)(n.strong,{children:"Neue Wahl importieren"}),": Eine neue Funktion \u201eImportiere Neue Wahl\u201c im Men\xfc \u201eDatei\u201c erlaubt den Import von bereits bestehenden Kandidierendenlisten im XLSX-Format. Die Struktur der Gremien, Wahlbereiche, Listen und Kandidat",":innen"," l\xe4sst sich somit direkt per Import anlegen. Insbesondere wenn die Kandidierendenlisten bereits vorliegen, eine hohe Anzahl von Wahlbereichen, Wahlvorschl\xe4gen und Kandidierenden gew\xe4hlt werden sollen oder Systeme zur Nominierung genutzt werden, l\xe4sst sich die Anlage eines Wahlprojekts somit deutlich beschleunigen. Nach dem Klick auf \u201eDatei / Importiere Neue Wahl\u201c erscheint ein Dialog zum Einlesen der Kandidierendenliste, in der neben den Kandidierenden auch die Gremien, Gruppen und Listen aufgef\xfchrt sein m\xfcssen. Ist keine Liste aufgef\xfchrt, werden Einzelkandidaten importiert. Es kann zudem eine WHL-Datei ausgew\xe4hlt werden, aus der bereits konfigurierte Daten (Wahlordnung, Textbausteine, Gremien, Wahlbereiche und Layout der Dokumente) \xfcbernommen werden sollen."]}),"\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsx)(n.strong,{children:"Mehrere Wahlprojekte in eigenen Arbeitsverzeichnissen"}),": Die Konfiguration des Arbeitsverzeichnisses arbeitet nun im Standardpfad \u201eC:\\Benutzer&lt;Nutzername>\\uniwahl\u201c mit mehreren Unterverzeichnissen. In diesem Verzeichnis angelegte Wahlprojekte lassen sich in der Benutzeroberfl\xe4che wechseln, ohne den Pfad im Windows Explorer explizit suchen zu m\xfcssen. Mehrere Wahlprojekte (z.B. sich wiederholende oder zusammenh\xe4ngende Wahlen) lassen sich nun leichter in Unterverzeichnissen organisieren und direkt in der Oberfl\xe4che wechseln. Die Ablage der Ausgabedateien von uniWAHL wird somit \xfcbersichtlicher strukturiert."]}),"\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsxs)(n.strong,{children:["Gremien, Statusgruppen, Listen und Kandidat",":innen"," kopieren"]}),": Durch einfachen Rechtsklick im linken Navigationsbereich auf ein Gremium, einen Wahlbereich, eine Liste oder Kandidat",":in"," erscheint ein Kontextmen\xfc, das ein leichtes Kopieren des markierten Inhalts erm\xf6glicht. Durch das Kopieren von Elementen der Gremienstruktur k\xf6nnen gr\xf6\xdfere Wahlprojekte mit vielen Gremien oder Wahlbereichen schneller angelegt werden. Au\xdferdem lassen sich Strukturelemente so verschieben, wenn z.B. ein",":e"," Kandidat",":in"," versehentlich falsch zugeordnet wurde."]}),"\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsx)(n.strong,{children:"Farbige Markierung am Stimmzettel (uniWAHL, uniSCAN, OWS)"}),": Der zentrale Dialog \u201eLayout der Dokumente\u201c im Men\xfc \u201eKonfiguration\u201c sowie die gruppenspezifischen Layouts enthalten nun einen Eintrag \u201eStimmzettelfarbe\u201c, mit dem farbliche Markierungen auf Stimmzetteln aufgebracht werden k\xf6nnen. Es kann leicht aus einer pastellfarbigen Palette ausgew\xe4hlt werden. Die Farbwahl kann sowohl f\xfcr Papier- als Online-Stimmzettel vorgenommen werden. Durch die farbliche Markierung steigt die \xdcbersichtlichkeit sowohl f\xfcr die Mitarbeiter",":innen"," der Wahlorganisation als auch f\xfcr Wahlberechtigte. Sie k\xf6nnen Stimmzettel somit leichter optisch voneinander unterscheiden, ohne farbiges Papier nutzen zu m\xfcssen. Mit farbigen Stimmzetteln wird u.U. auch der Vorgabe von Wahlordnungen Rechnung getragen. Wird eine farbliche Markierung im gruppenspezifischen Layout eines Wahlbereichs eingestellt, wird auch der Kopfbereich des Wahlbereichs analog eingef\xe4rbt, damit die Zuordnung der Stimmzettel zum Wahlbereich auch f\xfcr die Wahlleitungen und Wahlhelfer",":innen"," optisch besser zu unterscheiden ist."]}),"\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsx)(n.strong,{children:"Stimmzettel-Layout: Eine Liste pro Spalte (uniSCAN)"}),": Im Layout-Dialog (\u201eDatei / Layout der Dokumente\u201c) kann nun die Option \u201eEine Liste pro Spalte\u201c gew\xe4hlt werden. Dadurch werden Listen auf den Stimmzetteln nicht willk\xfcrlich umgebrochen, sondern nebeneinander dargestellt. Insbesondere bei Stimmzetteln mit sehr unterschiedlichen Kandidat",":innenzahlen"," innerhalb der Listen kann somit besser daf\xfcr gesorgt werden, dass die Listen in Spalten umbrechen. Mit \u201eListen in Spalten\u201c wird auch Formatierungsvorgaben von Wahlordnungen Rechnung getragen."]}),"\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsx)(n.strong,{children:"Ausgabetabelle enth\xe4lt weitere Spalten"}),": Die \u201eTabelle\u201c im Men\xfc \u201eAusgabe\u201c wurde um weitere Spalten erg\xe4nzt, um die \xdcbersicht \xfcber die Gremienstruktur weiter zu verbessern: Die Spalte \u201eGruppenID\u201c kann z.B. bei Export-/Importvorg\xe4ngen von Stimmen im Mehrplatzbetrieb helfen. \xdcber die Spalte \u201eLayout\u201c ist erkenntlich, in welchem Wahlbereich ein individuelles Layout benutzt wurde. Die Spalte \u201eStatus\u201c zeigt den Status der Wahlbereiche an. In der Spalte \u201eWahlberechtigte\u201c kann nachvollzogen werden, in welchen Wahlbereichen die Zahl der Wahlberechtigten bereits korrekt hinterlegt wurde."]}),"\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsx)(n.strong,{children:"Export des W\xe4hlerverzeichnis (uniWAHL Wahlraum)"}),": Das W\xe4hlerverzeichnis kann nun aus uniWAHL direkt im Importformat der uniWAHL Wahlraumsoftware ausgegeben werden. Dadurch wird der \xdcbertrag bereits durchgef\xfchrter Daten\xe4nderungen erleichtert (z.B. Markierung als Briefw\xe4hler",":in","). Die Daten des Wahlverzeichnisses aus uniWAHL k\xf6nnen somit noch leichter an Wahllokale \xfcbergeben werden. Mit Hilfe der uniWAHL Wahlraum Software k\xf6nnen Briefwahlantr\xe4ge und pers\xf6nliche Erkl\xe4rungen noch schneller verarbeitet bzw. die Wahlberechtigung von W\xe4hler",":innen"," in Pr\xe4senz- und Briefwahlen gepr\xfcft werden."]}),"\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsx)(n.strong,{children:"Verbesserte Formatierung von Texten"}),": Die Eingabefelder in den Textbausteinen f\xfcr Stimmzettel, Wahlvorschl\xe4ge und Wahlergebnis wurden vergr\xf6\xdfert und sind nun mehrzeilig nutzbar. Die Schriftart wurde angepasst, um die Lesbarkeit des Dialogs zu erh\xf6hen. Durch die \xdcberarbeitung des Textbaustein-Dialogs wird das Bearbeiten und Kontrollieren der Texte \xfcbersichtlicher. Insbesondere lange Texte werden nicht mehr abgeschnitten, sondern vollst\xe4ndig dargestellt."]}),"\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsx)(n.strong,{children:"Texte der Online-Wahl (uniWAHL OWS)"}),": Die Textinhalte der Wahlkabine im uniWAHL Onlinewahlsystem (OWS) lassen sich nun pro Wahlprojekt flexibel direkt im uniWAHL Kernprodukt hinterlegen. Die Texte sind mit einer Vorschau versehen, die den Ort der Darstellung des Texts im uniWAHL OWS anzeigen. Es k\xf6nnen Anleitungstexte, Stimmzettel-Auswahlseite, Stimmzettel, Verschl\xfcsselungsseite, \xdcbereilungsschutz und Stimmabgabe-Beleg als auch die Schaltfl\xe4chen textuell angepasst werden. Durch die Voransicht, Ver\xe4nderung und Speicherung der Texte kann direkt Einfluss auf die Online-Wahlkabine vorgenommen werden."]}),"\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsx)(n.strong,{children:"Layout der Online-Wahl"}),": Das Layout der Wahlkabine des uniWAHL OWS kann nun flexibel \xfcber den Layout-Dialog angepasst werden. Es stehen zahlreiche Funktionen zur Formatierung und inhaltlichem Aufbau zur Verf\xfcgung (Spalten, Stimmzettel-Nachverfolgung, Schaltfl\xe4chen, Weiterleitung). Der inhaltliche Aufbau kann pro Wahlbereich \xfcber den Layout-Dialog der Gruppe angepasst werden. Dadurch lassen sich unterschiedliche Darstellungen (z.B. Stimmzettelfarben) in den Wahlbereichen nutzen. Durch die selbstst\xe4ndige Konfiguration der Online-Wahlkabine steigt die Einsichts-, Konfigurations- und Kontrollm\xf6glichkeit der Wahlverantwortlichen. Durch individuelle inhaltliche Gestaltungsm\xf6glichkeiten pro Wahlbereich lassen sich Anforderungen verschiedener Wahlverantwortlicher leichter in einem Online-Wahlprojekt vereinen. Es k\xf6nnen z.B. individuelle Farben, Logos oder Weiterleitungen pro Stimmzettel vorgesehen werden."]}),"\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsx)(n.strong,{children:"Konfiguration des Online-Wahlsystems speichern"}),": Die Konfiguration zur \xdcbergabe der Daten an das uniWAHL Onlinewahlsystem wird nun beim ersten Export gespeichert und kann so beliebig oft wiederholt werden. Durch die Speicherung nach erstmaliger Konfiguration der \xdcbergabe an das Online-wahlsystem steigt die Einsichts-, Konfigurations- und Kontrollm\xf6glichkeiten der Wahlverantwortlichen. Insbesondere die Durchf\xfchrung aufeinander folgender Wahlprojekte wird dadurch erleichtert."]}),"\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsx)(n.strong,{children:"Neue Demo-Daten"}),": Die Demodaten der Anwendung wurden inhaltlich \xfcberabeitet. Es finden sich nun weitere Beispieldateien im Arbeitsverzeichnis, die den Einstieg in die Software erleichtern. Es wurden neue Demo-WHL-Dateien im Arbeitsverzeichnis erg\xe4nzt. Der Einstieg in die Software wird durch Nutzung von Beispieldateien und Dokumentenvorlagen weiter erleichtert. Weitere Gremienwahlen (Personal-/Betriebsrat, Vertreterwahlen) werden noch besser unterst\xfctzt."]}),"\n"]}),"\n",(0,t.jsx)(n.p,{children:"\u2699\ufe0fWeitere \xc4nderungen und Fehlerbehebungen"}),"\n",(0,t.jsxs)(n.ul,{children:["\n",(0,t.jsx)(n.li,{children:"\u2705Die Wahlordnungsoption (Listenwahl) \u201eBayHSchWO\u201c wurde in \u201ePerson oder Liste (kombiniert, verteilend)\u201c umbenannt."}),"\n",(0,t.jsx)(n.li,{children:"\u2705Es k\xf6nnen nun Kumulierzahlen > 9 eingegeben werden."}),"\n",(0,t.jsx)(n.li,{children:"\u2705Beim Zur\xfccksetzen eines Wahlbereichs (STRG+Z) werden nun auch alle Statistikwerte (G\xfcltige/Ung\xfcltige) zur\xfcckgesetzt."}),"\n",(0,t.jsx)(n.li,{children:"\u2705Die Dialogtexte und Fehlermeldungen wurden sprachlich \xfcberarbeitet."}),"\n",(0,t.jsx)(n.li,{children:"\u2705Personen im Wahlverzeichnis lassen sich nun leichter \xfcber die Tastenkombination (STRG+SHIFT+F) suchen und bearbeiten."}),"\n",(0,t.jsx)(n.li,{children:"\u2705In der Funktion \u201eWahlberechtigte z\xe4hlen\u2026\u201c kann nun auch eine Mehrfachauswahl (mit gedr\xfcckter STRG-Taste) genutzt werden."}),"\n",(0,t.jsx)(n.li,{children:"\u2705Die Funktion \u201eWahlverzeichnis aktualisieren\u201c wurde in \u201eBriefw\xe4hlende \xfcbertragen\u201c umbenannt, um die Funktion besser zu beschreiben."}),"\n",(0,t.jsxs)(n.li,{children:["\u2705Die Tabelle der Kandidat",":innen"," auf der Registerkarte \u201eZ\xe4hlen und Auswerten\u201c wurde \xfcberarbeitet (Vorname wird angezeigt, Spaltenbreite der Kandidat",":innen"," variierbar), um die manuelle Ausz\xe4hlung zu erleichtern."]}),"\n",(0,t.jsx)(n.li,{children:"\u2705URL-Unterst\xfctzung f\xfcr uniWAHL OWS, Word und LibreOffice: Im Layout-Dialog kann nun eine URL als Grafik-Datei hinterlegt werden (Alle Bildformate, SVG nur online)"}),"\n",(0,t.jsx)(n.li,{children:"\u2705Die Wahlordnungsoption wurde in \u201eErlaube >Ung\xfcltig< zu stimmen (nur online)\u201c ge\xe4ndert, da diese Option nur f\xfcr Online-Wahlen zur Verf\xfcgung steht."}),"\n",(0,t.jsx)(n.li,{children:"\u2705Die Wahlordnungsoptionen \u201eMehrheitswahl trotz mehrerer Listen\u201c, \u201eMehrheitswahl, wenn 1 Liste ...trotzdem Listenname \u201d und \u201eMehrheitswahl auch bei mehreren Listen m\xf6glich\u201c wurden auf die Registerkarte \u201eListenwahl\u201c verlegt, da es sich um Listenwahloptionen handelt."}),"\n",(0,t.jsx)(n.li,{children:"\u2705Der Mehrplatzbetrieb von uniWAHL wurde verbessert, da uniWAHL nun mit Dateien im Netzwerk besser arbeiten kann."}),"\n",(0,t.jsx)(n.li,{children:"\u2705Die Lizenz-Bestimmungen wurden \xfcberarbeitet. 30 Tage vor Ablauf weist uniWAHL beim Start nun in einem Dialog auf das Ablaufen der Lizenz hin."}),"\n",(0,t.jsx)(n.li,{children:"\u2705Die empfohlenen Schwellwerte f\xfcr uniSCAN wurden angepasst (Schw\xe4rzungsgrad wahrsch. Markierung = 6% und Schw\xe4rzungsgrad sicherer Markierung = 15 %)."}),"\n",(0,t.jsxs)(n.li,{children:["\u2705Die Funktion \u201eKandidateneingabe fertig (Alle Bereiche)\u201c wurde \xfcberarbeitet, so dass bestimmte Konstellationen noch besser ber\xfccksichtigt werden (Wahlbereich hat noch keine Kandidat",":innen",", Wahlbereich hat zu wenig Kandidat",":innen",")."]}),"\n"]})]})}function o(e={}){const{wrapper:n}={...(0,s.R)(),...e.components};return n?(0,t.jsx)(n,{...e,children:(0,t.jsx)(u,{...e})}):u(e)}},8453(e,n,i){i.d(n,{R:()=>a,x:()=>l});var r=i(6540);const t={},s=r.createContext(t);function a(e){const n=r.useContext(s);return r.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function l(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(t):e.components||t:a(e.components),r.createElement(s.Provider,{value:n},e.children)}}}]);